package presentation.snippets.lesson2.slide87

import presentation.support.*

fun describe(x: Int) = when (x) {
    in 1..10 if x % 2 == 0 -> "even, in 1..10"
    in 1..10 -> "odd, in 1..10"
    else -> "outside 1..10"
}
